// === todo.ts ===
export type Prioritas = "rendah" | "sedang" | "tinggi";
export type Todo = { readonly id: number; judul: string; selesai: boolean; prioritas: Prioritas };
export function format(t: Todo): string {
  return `[${t.selesai ? "x" : " "}] #${t.id} ${t.judul} (${t.prioritas})`;
}
// === store.ts ===
import type { Prioritas, Todo } from "./todo";
export type Result<T> = { ok: true; data: T } | { ok: false; error: string };
export class TodoStore {
  private todos: Todo[] = [];
  private idTerakhir = 0;
  tambah(judul: string, prioritas: Prioritas = "sedang"): Result<Todo> {
    if (judul.trim() === "") return { ok: false, error: "Judul kosong" };
    const t: Todo = { id: ++this.idTerakhir, judul: judul.trim(), selesai: false, prioritas };
    this.todos.push(t);
    return { ok: true, data: t };
  }
  selesaikan(id: number): Result<Todo> {
    const t = this.todos.find((x) => x.id === id);
    if (!t) return { ok: false, error: `#${id} tidak ada` };
    t.selesai = true;
    return { ok: true, data: t };
  }
  semua(): readonly Todo[] {
    return this.todos;
  }
}
// === main.ts ===
import { format } from "./todo";
import { TodoStore } from "./store";

const store = new TodoStore();
store.tambah("Belajar TypeScript", "tinggi");
store.tambah("Beli kopi", "rendah");
store.tambah("Kirim laporan");
const h = store.selesaikan(2);
if (!h.ok) console.log("Gagal:", h.error);
store.semua().forEach((t) => console.log(format(t)));

