// === todo.ts ===
export type Todo = { readonly id: number; judul: string; selesai: boolean };
export function aktif(daftar: readonly Todo[]): Todo[] {
  return daftar.filter((t) => !t.selesai);
}
// === main.ts ===
import { aktif, type Todo } from "./todo";
const daftar: Todo[] = [
  { id: 1, judul: "Belajar TypeScript", selesai: false },
  { id: 2, judul: "Beli kopi", selesai: true },
  { id: 3, judul: "Kirim laporan", selesai: false },
];
console.log(aktif(daftar).map((t) => t.judul).join(", "));
